css:
/* Force visible black table borders (default is a faint #d1d8dd) */
.print-format table.table-bordered,
.print-format table.table-bordered > thead > tr > th,
.print-format table.table-bordered > thead > tr > td,
.print-format table.table-bordered > tbody > tr > th,
.print-format table.table-bordered > tbody > tr > td {
	border: 1px solid #000 !important;
}

@media print {
	@page {
		size: A4 portrait;
		margin: 8mm;
	}

	html,
	body {
		height: auto !important;
		overflow: visible !important;
	}

	.print-format-gutter {
		padding: 0 !important;
		background: #fff !important;
	}

	.print-format {
		padding: 0 !important;
		margin: 0 !important;
		min-height: 0 !important;
		max-width: none !important;
		width: 100% !important;
		border-radius: 0 !important;
		box-shadow: none !important;
	}

	#header-html,
	#footer-html,
	footer,
	.bsp-print-footer {
		display: block !important;
	}
}

.bsp-watermark {
	position: fixed;
	left: 0;
	right: 0;
	top: 32%;
	z-index: 50;
	text-align: center;
	pointer-events: none;
}
.bsp-watermark img {
	width: 430px;
	opacity: 0.28;
}
.bsp-letterhead,
.bsp-letterhead div {
	text-align: center !important;
}
.print-format table.table-bordered > thead > tr > th,
.print-format table.table-bordered > tbody > tr > th,
.print-format table.table-bordered > tbody > tr > td {
	padding: 2px 6px !important;
	line-height: 1.15 !important;
}
.print-format table.table-bordered > tbody > tr > td {
	background-color: transparent !important;
}

.bsp-title-banner {
	display: table;
	width: 100%;
	margin: 4px 0 2px;
	border-collapse: separate;
}
.bsp-title-wing {
	display: table-cell;
	width: 28%;
	vertical-align: middle;
	padding: 0 8px;
}
.bsp-wing-top {
	border-top: 3px solid #1b8a44;
	margin: 0 0 3px;
	height: 0;
}
.bsp-wing-bottom {
	border-top: 2px solid #0d3b7a;
	height: 0;
}
.bsp-title-center {
	display: table-cell;
	width: 44%;
	text-align: center;
	vertical-align: middle;
}
.bsp-title-box {
	display: inline-block;
	background-color: #0d3b7a !important;
	color: #ffffff !important;
	font-size: 19px;
	font-weight: 800;
	padding: 4px 26px;
	letter-spacing: 1px;
	white-space: nowrap !important;
	border-left: 5px solid #1b8a44 !important;
	border-right: 5px solid #1b8a44 !important;
	-webkit-transform: skewX(-15deg);
	transform: skewX(-15deg);
}
.bsp-title-box span {
	display: inline-block;
	color: #ffffff !important;
	white-space: nowrap !important;
	-webkit-transform: skewX(15deg);
	transform: skewX(15deg);
}
table.bsp-sheet {
	width: 100%;
	height: auto;
	min-height: 242mm;
	border-collapse: collapse;
	border: none !important;
	page-break-inside: auto;
}
table.bsp-sheet tr {
	page-break-inside: auto;
}
table.bsp-sheet > tbody > tr > td {
	border: none !important;
	background: transparent !important;
	padding: 0 !important;
	vertical-align: top;
}
table.bsp-sheet > tbody > tr > td.bsp-sheet-foot {
	vertical-align: bottom;
}
.bsp-signoff {
	margin-top: 100px;
	page-break-inside: avoid;
	padding-top: 8px;
}
